import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        long N = in.nextLong();
        long M = in.nextLong();
        int K = in.nextInt();
        long invM = modPow(M, MOD - 2, MOD);
        long mod = invM;
        long[] expect = new long[K + 1];
        expect[0] = 1;
        long[] poly = new long[K + 1];
        poly[0] = 1;
        long curExpect = 1;
        for (int k = 1; k <= K; k++) {
            curExpect = (curExpect * (N - (k - 1))) % MOD;
            curExpect = (curExpect * mod) % MOD;
            for (int i = k; i >= 0; i--) {
                poly[i] = (i > 0 ? poly[i - 1] : 0) + (-(k - 1)) * poly[i];
                poly[i] = (poly[i] % MOD + MOD) % MOD;
            }
            expect[k] = curExpect;
            for (int i = k - 1; i >= 0; i--) {
                expect[k] = (expect[k] - poly[i] * expect[i]) % MOD;
                expect[k] = (expect[k] + MOD) % MOD;
            }
        }
        out.println(expect[K]);
        out.close();
    }

    static long modPow(long a, long e, long mod) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = (res * a) % mod;
            a = (a * a) % mod;
            e >>= 1;
        }
        return res;
    }

    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        public InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
            st = null;
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}
